"""Shared pytest fixtures for the metaphysica test suite."""
from __future__ import annotations

import os
import sys
from pathlib import Path

# Make sibling-of-tests modules importable when running pytest from any cwd.
ROOT = Path(__file__).resolve().parent.parent
SRC = ROOT / "src"
if str(SRC) not in sys.path:
    sys.path.insert(0, str(SRC))


# ── where the package looks for build artifacts ─────────────────────────────
#
# The PACKAGE resolves artifacts through `generators._common.autogen_dir()`,
# which is `METAPHYSICA_OUT / AutoGenerated` and falls back to the CURRENT
# WORKING DIRECTORY. Under pytest that is the repo root, so every package-side
# reader -- the declarative gate strategies, the certificate loader, the rigor
# validator -- looked in `metaphysica/AutoGenerated` and nowhere else, while
# the published artifacts sat in the sibling `PrincipiaMetaphysica` checkout.
# That is not something the package should be taught about: a library has no
# business knowing the layout of someone's two checkouts. METAPHYSICA_OUT is
# exactly the channel for saying where the build is, so the test session says
# it, once, here.
#
# Worse than merely missing them, `autogen_dir()` MKDIRS on the way past. A
# read path with a side effect meant that any test touching it CREATED an
# empty `metaphysica/AutoGenerated`, which then satisfied every `is_dir()`
# candidate check and shadowed the real tree for the rest of the session.
#
# Set only when the caller has not already chosen, so an explicit
# METAPHYSICA_OUT still wins and per-test monkeypatching is unaffected.
if not os.environ.get("METAPHYSICA_OUT"):
    for _root in (ROOT, ROOT.parent / "PrincipiaMetaphysica",
                  Path("H:/Github/PrincipiaMetaphysica")):
        if (_root / "AutoGenerated" / "parameters.json").is_file():
            os.environ["METAPHYSICA_OUT"] = str(_root)
            break
